enum CountError: Error {
    case emptyInput
}

func wordCounts(in text: String) throws -> [String: Int] {
    guard !text.isEmpty else {
        throw CountError.emptyInput
    }
    var counts: [String: Int] = [:]
    for word in text.lowercased().split(separator: " ") {
        counts[String(word), default: 0] += 1
    }
    return counts
}

