protocol DataSource {
    associatedtype Item

    func load() async throws -> [Item]
}

struct MemorySource<Item>: DataSource {
    let items: [Item]

    func load() async throws -> [Item] {
        return items
    }
}

enum PipelineError: Error {
    case empty
}

func top<Source: DataSource>(
    from source: Source,
    by isBetter: (Source.Item, Source.Item) -> Bool
) async throws -> Source.Item {
    let items = try await source.load()
    let ranked = items.sorted(by: isBetter)
    guard let best = ranked.first else {
        throw PipelineError.empty
    }
    return best
}

