func linearSearch(_ values: [Int], target: Int) -> Int? {
    for (index, value) in values.enumerated() where value == target {
        return index
    }
    return nil
}

func binarySearch(_ values: [Int], target: Int) -> Int? {
    var low = 0
    var high = values.count - 1

    while low <= high {
        let mid = low + (high - low) / 2
        if values[mid] == target {
            return mid
        } else if values[mid] < target {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    return nil
}

func bubbleSort(_ values: [Int]) -> [Int] {
    var sorted = values
    guard sorted.count > 1 else {
        return sorted
    }
    for end in stride(from: sorted.count - 1, through: 1, by: -1) {
        var swapped = false
        for i in 0..<end {
            if sorted[i] > sorted[i + 1] {
                sorted.swapAt(i, i + 1)
                swapped = true
            }
        }
        if !swapped {
            break
        }
    }
    return sorted
}

func selectionSort(_ values: [Int]) -> [Int] {
    var sorted = values
    for i in 0..<sorted.count {
        var minIndex = i
        for j in (i + 1)..<sorted.count where sorted[j] < sorted[minIndex] {
            minIndex = j
        }
        if minIndex != i {
            sorted.swapAt(i, minIndex)
        }
    }
    return sorted
}

func insertionSort(_ values: [Int]) -> [Int] {
    var sorted = values
    guard sorted.count > 1 else {
        return sorted
    }
    for i in 1..<sorted.count {
        let current = sorted[i]
        var j = i - 1
        while j >= 0 && sorted[j] > current {
            sorted[j + 1] = sorted[j]
            j -= 1
        }
        sorted[j + 1] = current
    }
    return sorted
}

func mergeSort(_ values: [Int]) -> [Int] {
    guard values.count > 1 else {
        return values
    }
    let mid = values.count / 2
    let left = mergeSort(Array(values[..<mid]))
    let right = mergeSort(Array(values[mid...]))
    return merge(left, right)
}

func merge(_ left: [Int], _ right: [Int]) -> [Int] {
    var result: [Int] = []
    result.reserveCapacity(left.count + right.count)

    var i = 0
    var j = 0
    while i < left.count && j < right.count {
        if left[i] <= right[j] {
            result.append(left[i])
            i += 1
        } else {
            result.append(right[j])
            j += 1
        }
    }

    result.append(contentsOf: left[i...])
    result.append(contentsOf: right[j...])
    return result
}

func quickSort(_ values: [Int]) -> [Int] {
    guard let pivot = values.first else {
        return []
    }
    let rest = values.dropFirst()
    let smaller = rest.filter { $0 < pivot }
    let equal = rest.filter { $0 == pivot }
    let larger = rest.filter { $0 > pivot }
    return quickSort(smaller) + [pivot] + equal + quickSort(larger)
}

func heapSort(_ values: [Int]) -> [Int] {
    var sorted = values
    let n = sorted.count
    guard n > 1 else {
        return sorted
    }
    for i in stride(from: n / 2 - 1, through: 0, by: -1) {
        siftDown(&sorted, root: i, size: n)
    }
    for end in stride(from: n - 1, through: 1, by: -1) {
        sorted.swapAt(0, end)
        siftDown(&sorted, root: 0, size: end)
    }
    return sorted
}

func siftDown(_ values: inout [Int], root: Int, size: Int) {
    var largest = root
    let left = 2 * root + 1
    let right = 2 * root + 2
    if left < size && values[left] > values[largest] {
        largest = left
    }
    if right < size && values[right] > values[largest] {
        largest = right
    }
    if largest != root {
        values.swapAt(root, largest)
        siftDown(&values, root: largest, size: size)
    }
}

struct Graph {
    private var edges: [String: [String]] = [:]

    mutating func addEdge(_ from: String, _ to: String) {
        edges[from, default: []].append(to)
        edges[to, default: []].append(from)
    }

    func neighbors(of node: String) -> [String] {
        return edges[node] ?? []
    }
}

func bfs(_ graph: Graph, from start: String) -> [String] {
    var visited: Set<String> = [start]
    var queue = [start]
    var order: [String] = []
    var index = 0

    while index < queue.count {
        let node = queue[index]
        index += 1
        order.append(node)
        for neighbor in graph.neighbors(of: node) {
            if visited.insert(neighbor).inserted {
                queue.append(neighbor)
            }
        }
    }
    return order
}

func dfs(_ graph: Graph, from start: String) -> [String] {
    var visited: Set<String> = []
    var order: [String] = []
    visit(graph, node: start, visited: &visited, order: &order)
    return order
}

func visit(
    _ graph: Graph,
    node: String,
    visited: inout Set<String>,
    order: inout [String]
) {
    guard visited.insert(node).inserted else {
        return
    }
    order.append(node)
    for neighbor in graph.neighbors(of: node) {
        visit(graph, node: neighbor, visited: &visited, order: &order)
    }
}

struct WeightedGraph {
    private var edges: [String: [(to: String, weight: Int)]] = [:]

    mutating func addEdge(_ from: String, _ to: String, weight: Int) {
        edges[from, default: []].append((to, weight))
        edges[to, default: []].append((from, weight))
    }

    func neighbors(of node: String) -> [(to: String, weight: Int)] {
        return edges[node] ?? []
    }
}

func dijkstra(_ graph: WeightedGraph, from start: String) -> [String: Int] {
    var distances: [String: Int] = [start: 0]
    var visited: Set<String> = []

    while true {
        var current: String?
        var best = Int.max
        for (node, distance) in distances where !visited.contains(node) {
            if distance < best {
                best = distance
                current = node
            }
        }
        guard let node = current else {
            break
        }
        visited.insert(node)
        for edge in graph.neighbors(of: node) {
            guard best <= Int.max - edge.weight else {
                continue
            }
            let candidate = best + edge.weight
            if candidate < distances[edge.to, default: Int.max] {
                distances[edge.to] = candidate
            }
        }
    }
    return distances
}
